from collections import OrderedDict
cache, SIZE = OrderedDict(a=1, b=2, c=3), 3   # a is the oldest
def get(key):
    if key in cache:
        cache.move_to_end(key)        # mark as newest
    return cache.get(key, -1)
def put(key, value):
    cache[key] = value
    cache.move_to_end(key)
    if len(cache) > SIZE:
        cache.popitem(last=False)     # drop the oldest
print(get("a"))
put("d", 4)
print(get("b"), list(cache))
